// FUNCTION: BFME2 0x00090360 size=33 name=??0W3DDisplayStringManager@@QAE@XZ evidence=N:ledger tier=B hypothesis:name:Z
W3DDisplayStringManager::W3DDisplayStringManager()
{
	for (int i = 0; i < MAX_GROUPS; i++)
		m_groupNumeralStrings[i] = 0;
	m_formationLetterDisplayString = 0;
}

// FUNCTION: BFME2 0x00090381 size=47 name=?freeDisplayString@W3DDisplayStringManager@@UAEXPAVDisplayString@@@Z evidence=N:ledger tier=B hypothesis:cohesion
void W3DDisplayStringManager::freeDisplayString(DisplayString *string)
{
	if (string != 0)
	{
		unLink(string);
		if (m_currentCheckpoint == string)
			m_currentCheckpoint = 0;
		::delete string;
	}
}

// FUNCTION: BFME2 0x000903B0 size=103 name=?update@W3DDisplayStringManager@@UAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void W3DDisplayStringManager::update()
{
	W3DDisplayString *string = (W3DDisplayString *)m_stringList;

	if (m_currentCheckpoint)
		string = (W3DDisplayString *)m_currentCheckpoint;

	UnsignedInt currFrame = TheGameClient->getFrame();
	const UnsignedInt w3dCleanupTime = 60;

	int numStrings = 10;
	while (numStrings-- && string)
	{
		if (string->m_lastResourceFrame != 0 && currFrame - string->m_lastResourceFrame > w3dCleanupTime)
		{
			string->m_textRenderer.Reset();
			string->m_hotKeyRenderer.Reset();
			string->m_textChanged = true;
			string->m_lastResourceFrame = 0;
		}

		string = (W3DDisplayString *)string->next();
	}

	m_currentCheckpoint = string;
}

// FUNCTION: BFME2 0x00090417 size=25 name=?getGroupNumeralString@W3DDisplayStringManager@@UAEPAVDisplayString@@H@Z evidence=N:ledger tier=B hypothesis:cohesion
DisplayString *W3DDisplayStringManager::getGroupNumeralString(int numeral)
{
	if (numeral < 0 || numeral > 9)
		return m_groupNumeralStrings[0];
	return m_groupNumeralStrings[numeral];
}

// FUNCTION: BFME2 0x00090430 size=46 name=?reset@W3DDisplayStringManager@@UAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void W3DDisplayStringManager::reset()
{
	W3DDisplayString *string = (W3DDisplayString *)m_stringList;
	while (string)
	{
		string->m_textRenderer.Reset();
		string->m_hotKeyRenderer.Reset();
		string->m_lastResourceFrame = 0;
		string->m_textChanged = true;
		string = (W3DDisplayString *)string->next();
	}
}

// FUNCTION: BFME2 0x0009045E size=108 name=??1W3DDisplayStringManager@@UAE@XZ evidence=N:ledger tier=B hypothesis:cohesion
W3DDisplayStringManager::~W3DDisplayStringManager()
{
	for (int i = 0; i < MAX_GROUPS; i++)
	{
		if (m_groupNumeralStrings[i])
			freeDisplayString(m_groupNumeralStrings[i]);
		m_groupNumeralStrings[i] = 0;
	}
	if (m_formationLetterDisplayString)
		freeDisplayString(m_formationLetterDisplayString);
	m_formationLetterDisplayString = 0;
}

// FUNCTION: BFME2 0x000904CA size=266 name=?postProcessLoad@W3DDisplayStringManager@@UAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void W3DDisplayStringManager::postProcessLoad( void )
{
	// Get the font.
	GameFont *font = TheFontLibrary->getFont(
		&TheDrawGroupInfo->m_fontName,
		TheDrawGroupInfo->m_fontSize,
		TheDrawGroupInfo->m_fontIsBold );
	
	for (Int i = 0; i < MAX_GROUPS; ++i)
	{
		m_groupNumeralStrings[i] = newDisplayString();
		m_groupNumeralStrings[i]->setFont(font);

 		AsciiString displayNumber;
 		displayNumber.format("NUMBER:%d", i);
 		m_groupNumeralStrings[i]->setText(TheGameText->fetch(displayNumber));
	}

	m_formationLetterDisplayString = newDisplayString();
	m_formationLetterDisplayString->setFont(font);
	AsciiString displayLetter;
	displayLetter.format("LABEL:FORMATION");
	m_formationLetterDisplayString->setText(TheGameText->fetch(displayLetter));

}

// FUNCTION: BFME2 0x000905F0 size=238 name=?newDisplayString@W3DDisplayStringManager@@UAEPAVDisplayString@@XZ evidence=N:ledger tier=B hypothesis:cohesion
DisplayString *W3DDisplayStringManager::newDisplayString()
{
	DisplayString *newString = new W3DDisplayString;

	if (newString == 0)
		return 0;

	if (TheGlobalLanguageData && !TheGlobalLanguageData->m_defaultDisplayStringFont.name.isEmpty())
	{
		newString->setFont(TheFontLibrary->getFont(
			&TheGlobalLanguageData->m_defaultDisplayStringFont.name,
			TheGlobalLanguageData->m_defaultDisplayStringFont.size,
			TheGlobalLanguageData->m_defaultDisplayStringFont.bold));
	}
	else
	{
		AsciiString fontName("Times New Roman");
		newString->setFont(TheFontLibrary->getFont(&fontName, 12, false));
	}

	link(newString);

	return newString;
}

